window.GUIDED=[{"num": 1, "hook": "A well-read trainee cannot answer a patient who asks whether a treatment is worth its burden. What is missing?", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-001-1", "level": "Essentials", "title": "What does evidence-based healthcare use population research to inform?", "explanation": "Decisions about individual patients, with benefits and harms interpreted in their clinical context.", "pdf_page": 20, "card_id": "fc-001-1"}, {"id": "u-001-2", "level": "Essentials", "title": "What are the five broad steps of evidence-based practice?", "explanation": "Formulate an answerable question; find evidence; appraise validity and usefulness; implement; evaluate performance.", "pdf_page": 21, "card_id": "fc-001-2"}, {"id": "u-001-3", "level": "Application", "title": "Why is critical appraisal alone insufficient?", "explanation": "The question and source must fit the problem, and valid findings must be implemented and evaluated.", "pdf_page": 22, "card_id": "fc-001-3"}, {"id": "u-001-4", "level": "Application", "title": "What four components make a focused intervention question?", "explanation": "Population, intervention, comparison and outcomes that matter; the manoeuvre may instead be an exposure or test.", "pdf_page": 31, "card_id": "fc-001-4"}, {"id": "u-001-5", "level": "Deep Dive", "title": "Why can a factual essay fail to solve a patient's problem?", "explanation": "It may describe a condition without isolating the practical decision and information the patient needs.", "pdf_page": 30, "card_id": "fc-001-5"}, {"id": "u-001-6", "level": "Deep Dive", "title": "Why must patient preferences enter question formulation?", "explanation": "The relevant outcome and acceptable trade-offs depend on the particular patient's circumstances and values.", "pdf_page": 31, "card_id": "fc-001-6"}], "outcomes": [{"id": "o-001-1", "text": "Select and justify the best response: A journal club asks whether home monitoring improves care. The intended decision is whether to offer it to frail adults who value avoiding hospital visits. The team can obtain only one additional item of information before searching. Which would most improve the decision question?", "pdf_page": 31, "assessment_id": "q-001-1"}, {"id": "o-001-2", "text": "Select and justify the best response: A team has framed a precise question, found an applicable review and checked its methods. Three months after circulating it, prescribing is unchanged. The stated goal is to improve practice rather than reading skill. Which next step best addresses the current failure?", "pdf_page": 21, "assessment_id": "q-001-2"}, {"id": "o-001-3", "text": "Select and justify the best response: Two clinicians agree on the estimated benefits and harms of a preventive treatment. One patient prioritises a small reduction in future risk; another prioritises avoiding daily treatment. Which part of the evidence-based process most directly accounts for different reasonable choices?", "pdf_page": 31, "assessment_id": "q-001-3"}, {"id": "o-001-4", "text": "Select and justify the best response: Assertion (A): A population estimate can inform a decision without determining the individual patient’s choice.\n\nReason (R): The estimate and its confidence interval describe uncertainty in the population effect.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 20, "assessment_id": "q-001-4"}, {"id": "o-001-5", "text": "Select and justify the best response: An audit records five completed activities: 40 questions formulated, 35 searches documented, 30 papers appraised, 25 evidence summaries emailed and 20 practice changes measured. The team labels emailing as implementation. Which additional observation would best distinguish dissemination from implementation?", "pdf_page": 22, "assessment_id": "q-001-5"}], "case_ids": ["q-001-1", "q-001-3"]}, {"num": 2, "hook": "You have ten minutes for a clinical answer; your colleague is planning a comprehensive review. Should your searches be the same?", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-002-1", "level": "Essentials", "title": "What three purposes shape a literature search?", "explanation": "Browsing to keep current, answering a focused clinical question, and comprehensively surveying a research topic.", "pdf_page": 35, "card_id": "fc-002-1"}, {"id": "u-002-2", "level": "Essentials", "title": "When can a focused clinical search reasonably stop?", "explanation": "When trustworthy, relevant information has been found; this is different from an exhaustive research review.", "pdf_page": 36, "card_id": "fc-002-2"}, {"id": "u-002-3", "level": "Application", "title": "Why is a single simple database query inadequate for a comprehensive review?", "explanation": "A review needs systematic searching of relevant databases and citation chaining, usually with an information professional.", "pdf_page": 36, "card_id": "fc-002-3"}, {"id": "u-002-4", "level": "Application", "title": "What can a systematic review inherit from its primary studies?", "explanation": "Their methodological or design flaws; synthesis does not automatically remove those flaws.", "pdf_page": 38, "card_id": "fc-002-4"}, {"id": "u-002-5", "level": "Deep Dive", "title": "How can secondary sources help locate primary research?", "explanation": "Their references and hyperlinks provide routes to relevant original studies.", "pdf_page": 42, "card_id": "fc-002-5"}, {"id": "u-002-6", "level": "Deep Dive", "title": "What is the attraction of a federated search engine?", "explanation": "It searches several types of evidence resource at once; search convenience still does not establish evidence quality.", "pdf_page": 44, "card_id": "fc-002-6"}], "outcomes": [{"id": "o-002-1", "text": "Select and justify the best response: A librarian supports two projects about the same treatment. Project X needs an answer for tomorrow's consultation; project Y will claim a comprehensive map of the research. Both have found the same credible recent synthesis. Which difference in stopping rules is most defensible?", "pdf_page": 36, "assessment_id": "q-002-1"}, {"id": "o-002-2", "text": "Select and justify the best response: A review pools several trials, all comparing the new drug with a subtherapeutic comparator dose. The pooled confidence interval is narrow. Which concern most limits its answer to a question about comparison with adequate standard care?", "pdf_page": 38, "assessment_id": "q-002-2"}, {"id": "o-002-3", "text": "Select and justify the best response: A trainee searches a familiar database with two text words and retrieves no relevant primary studies. A suitable secondary source contains several apparently eligible studies not retrieved. What is the most informative first response?", "pdf_page": 42, "assessment_id": "q-002-3"}, {"id": "o-002-4", "text": "Select and justify the best response: Assertion (A): A single brief database search can be insufficient for a comprehensive review.\n\nReason (R): Relevant studies may be found only through additional databases or citation chaining.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 36, "assessment_id": "q-002-4"}, {"id": "o-002-5", "text": "Select and justify the best response: Search A retrieves 12 relevant papers from one database. Search B retrieves those 12 plus 3 relevant reports through citation chaining and a second database. A proposal states that A was comprehensive because its papers were high quality. Which observation directly challenges that claim?", "pdf_page": 36, "assessment_id": "q-002-5"}], "case_ids": ["q-002-1", "q-002-3"]}, {"num": 3, "hook": "Before reading a result, identify how the study was designed and whether that design can answer its question.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-003-1", "level": "Essentials", "title": "What three preliminary questions orient a paper appraisal?", "explanation": "Why was the study needed and what was the question; what was the design; and was that design appropriate to the question?", "pdf_page": 51, "card_id": "fc-003-1"}, {"id": "u-003-2", "level": "Essentials", "title": "What distinguishes a randomised controlled trial?", "explanation": "Participants are allocated by a random process to comparison groups and followed for prespecified outcomes.", "pdf_page": 53, "card_id": "fc-003-2"}, {"id": "u-003-3", "level": "Application", "title": "Does having a control group prove a study was randomised?", "explanation": "No. Allocation can be non-random even when an intervention and control group are compared.", "pdf_page": 54, "card_id": "fc-003-3"}, {"id": "u-003-4", "level": "Application", "title": "Why might qualitative methods be needed when evaluating care?", "explanation": "Patients may value aspects of an experience that standard numerical outcomes do not capture.", "pdf_page": 57, "card_id": "fc-003-4"}, {"id": "u-003-5", "level": "Deep Dive", "title": "What is the starting point of a case-control study?", "explanation": "Select people with a condition and suitable controls, then investigate previous exposures.", "pdf_page": 59, "card_id": "fc-003-5"}, {"id": "u-003-6", "level": "Deep Dive", "title": "Why is an RCT not the best design for every question?", "explanation": "RCTs are particularly suited to intervention questions; other questions require other designs or methods.", "pdf_page": 55, "card_id": "fc-003-6"}], "outcomes": [{"id": "o-003-1", "text": "Select and justify the best response: Investigators recruit 80 people with a rare disorder and 160 people without it from the same source population. They compare recorded exposure before diagnosis. Which design-specific concern most directly deserves appraisal?", "pdf_page": 59, "assessment_id": "q-003-1"}, {"id": "o-003-2", "text": "Select and justify the best response: Ward teams chose their diets before a study began: ward A uses one diet and ward B another. The hospital randomly selected those two wards from ten available wards. The report calls the comparison an RCT because of that random ward selection. Which feature prevents the stated method from justifying the label?", "pdf_page": 54, "assessment_id": "q-003-2"}, {"id": "o-003-3", "text": "Select and justify the best response: Before comparing two procedures, researchers find that clinicians define success as technical completion, whereas patients emphasise pain, predictability and privacy. The immediate task is to clarify which outcomes should enter the evaluation. Which study is most directly useful next?", "pdf_page": 57, "assessment_id": "q-003-3"}, {"id": "o-003-4", "text": "Select and justify the best response: Assertion (A): An RCT is the preferred design for every question about patients’ experiences of care.\n\nReason (R): Random allocation can reduce baseline differences between intervention groups.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 55, "assessment_id": "q-003-4"}, {"id": "o-003-5", "text": "Select and justify the best response: Three reports are available. X randomly assigns treatment then follows outcomes. Y selects exposed and unexposed people then follows outcomes. Z selects people with and without the outcome then checks earlier exposure. Which pairing is correct?", "pdf_page": 53, "assessment_id": "q-003-5"}], "case_ids": ["q-003-1", "q-003-3"]}, {"num": 4, "hook": "A large, impressive study may still answer the wrong question or measure the wrong thing.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-004-1", "level": "Essentials", "title": "Why inspect recruitment and exclusion criteria?", "explanation": "They determine who was studied and whether findings can reasonably apply to the people you care for.", "pdf_page": 66, "card_id": "fc-004-1"}, {"id": "u-004-2", "level": "Essentials", "title": "Why distinguish recorded care from actual care?", "explanation": "Medical records or self-reports may measure documentation or stated behaviour rather than what happened.", "pdf_page": 67, "card_id": "fc-004-2"}, {"id": "u-004-3", "level": "Application", "title": "What should a validated outcome measure demonstrate?", "explanation": "That it measures the intended construct and that changes reasonably reflect changes in the patient's status.", "pdf_page": 68, "card_id": "fc-004-3"}, {"id": "u-004-4", "level": "Application", "title": "Why does randomisation not end the search for bias?", "explanation": "Bias can still enter through recruitment, allocation procedures, follow-up or assessment.", "pdf_page": 69, "card_id": "fc-004-4"}, {"id": "u-004-5", "level": "Deep Dive", "title": "What is the purpose of blinded assessment?", "explanation": "Reduce the influence of knowledge or expectations about treatment allocation on outcome assessment.", "pdf_page": 73, "card_id": "fc-004-5"}, {"id": "u-004-6", "level": "Deep Dive", "title": "Why examine statistical power before accepting a negative result?", "explanation": "A study may be too small to detect an important difference; absence of statistical significance need not establish no effect.", "pdf_page": 74, "card_id": "fc-004-6"}], "outcomes": [{"id": "o-004-1", "text": "Select and justify the best response: An audit counts whether smoking status appears in clinical records and concludes that clinicians asked about smoking in exactly that proportion of consultations. A validation substudy is affordable. Which comparison most directly tests the disputed inference?", "pdf_page": 67, "assessment_id": "q-004-1"}, {"id": "o-004-2", "text": "Select and justify the best response: A trial cannot blind patients to a rehabilitation programme. The primary outcome is a subjective clinician-rated function score. Which feasible safeguard most directly addresses detection bias?", "pdf_page": 73, "assessment_id": "q-004-2"}, {"id": "o-004-3", "text": "Select and justify the best response: A well-conducted trial excludes people over 80 and those with multiple illnesses. Its result is being considered for a frail 86-year-old. Which first appraisal question most directly addresses the present uncertainty?", "pdf_page": 66, "assessment_id": "q-004-3"}, {"id": "o-004-4", "text": "Select and justify the best response: Assertion (A): A reproducible outcome scale necessarily measures the construct that matters to patients.\n\nReason (R): Reliability and validity describe the same measurement property.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 68, "assessment_id": "q-004-4"}, {"id": "o-004-5", "text": "Select and justify the best response: A trial was planned to detect a large benefit. Its result is not statistically significant, but the interval remains compatible with a smaller benefit clinicians would still value. Which conclusion best fits the information?", "pdf_page": 74, "assessment_id": "q-004-5"}], "case_ids": ["q-004-1", "q-004-3"]}, {"num": 5, "hook": "A p-value is reported as the whole result. What else must you know before deciding whether the finding matters?", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-005-1", "level": "Essentials", "title": "What should be examined in baseline group characteristics?", "explanation": "Whether groups differ in important prognostic factors and whether appropriate adjustments were considered.", "pdf_page": 84, "card_id": "fc-005-1"}, {"id": "u-005-2", "level": "Essentials", "title": "When are observations paired?", "explanation": "When measurements are linked, such as before-and-after observations on the same individual.", "pdf_page": 90, "card_id": "fc-005-2"}, {"id": "u-005-3", "level": "Application", "title": "Why is a two-sided test generally appropriate?", "explanation": "An intervention can plausibly improve or worsen the outcome unless a one-direction assumption is convincingly justified.", "pdf_page": 91, "card_id": "fc-005-3"}, {"id": "u-005-4", "level": "Application", "title": "Why is a non-significant p-value not proof of no difference?", "explanation": "The study may lack enough information to detect a difference; significance alone cannot distinguish this from no effect.", "pdf_page": 94, "card_id": "fc-005-4"}, {"id": "u-005-5", "level": "Deep Dive", "title": "What do confidence intervals add to a point estimate?", "explanation": "They describe precision and the range of effect sizes compatible with the estimate under the model.", "pdf_page": 95, "card_id": "fc-005-5"}, {"id": "u-005-6", "level": "Deep Dive", "title": "Why express benefit in absolute as well as relative terms?", "explanation": "Relative reductions can obscure baseline risk; absolute effects and numbers needed to treat put benefit into context.", "pdf_page": 97, "card_id": "fc-005-6"}], "outcomes": [{"id": "o-005-1", "text": "Select and justify the best response: A trial estimates a risk ratio of 0.86 with a 95% confidence interval of 0.64–1.16. A reviewer calls it evidence of no benefit. What is the most defensible correction?", "pdf_page": 95, "assessment_id": "q-005-1"}, {"id": "o-005-2", "text": "Select and justify the best response: Investigators compare before-and-after symptom scores from the same 60 participants using a test for two independent samples. What feature is the main reason to reconsider that analysis?", "pdf_page": 90, "assessment_id": "q-005-2"}, {"id": "o-005-3", "text": "Select and justify the best response: A trial protocol prespecifies one primary comparison. The paper instead highlights a significant result found after exploring 18 subgroups, while the primary comparison is nonsignificant. Which additional information best addresses the credibility of the subgroup claim?", "pdf_page": 94, "assessment_id": "q-005-3"}, {"id": "o-005-4", "text": "Select and justify the best response: Assertion (A): A nonsignificant result is insufficient to establish that an important effect is absent.\n\nReason (R): A study can lack enough information to distinguish an important effect from no effect.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 94, "assessment_id": "q-005-4"}, {"id": "o-005-5", "text": "Select and justify the best response: Two programmes each reduce relative event risk by 25% over one year. Baseline risk is 20% in population X and 4% in population Y. Assuming the stated relative effect applies in both populations, which absolute-risk comparison is correct?", "pdf_page": 97, "assessment_id": "q-005-5"}], "case_ids": ["q-005-1", "q-005-3"]}, {"num": 6, "hook": "A new treatment changes a laboratory marker. Has it improved outcomes that patients value?", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-006-1", "level": "Essentials", "title": "What is a clinical trial of a simple intervention?", "explanation": "An evaluation of a well-defined intervention, often comparing it with a control or alternative treatment.", "pdf_page": 101, "card_id": "fc-006-1"}, {"id": "u-006-2", "level": "Essentials", "title": "Why examine the comparator in a drug trial?", "explanation": "An inappropriate alternative, dose or schedule can make the new intervention appear more favourable.", "pdf_page": 106, "card_id": "fc-006-2"}, {"id": "u-006-3", "level": "Application", "title": "Why inspect patient selection in a treatment trial?", "explanation": "The benefit-harm balance may not transfer to patients with different characteristics or comorbidities.", "pdf_page": 106, "card_id": "fc-006-3"}, {"id": "u-006-4", "level": "Application", "title": "What is a surrogate endpoint?", "explanation": "An intermediate measure used in place of a more directly patient-important outcome; its predictive validity needs evidence.", "pdf_page": 107, "card_id": "fc-006-4"}, {"id": "u-006-5", "level": "Deep Dive", "title": "Why can a plausible surrogate mislead?", "explanation": "Changing a marker need not produce the expected benefit in clinical outcomes, particularly if other effects intervene.", "pdf_page": 110, "card_id": "fc-006-5"}, {"id": "u-006-6", "level": "Deep Dive", "title": "Why can an efficacy RCT miss rare serious harms?", "explanation": "Trials powered for common efficacy outcomes are often too small to detect events occurring only once in many thousands.", "pdf_page": 113, "card_id": "fc-006-6"}], "outcomes": [{"id": "o-006-1", "text": "Select and justify the best response: A new drug is compared with a recognised standard. The standard is given at a lower dose than recommended for the question being studied. The new drug performs better on the primary endpoint. Which limitation most directly affects a claim of superiority to adequate standard treatment?", "pdf_page": 106, "assessment_id": "q-006-1"}, {"id": "o-006-2", "text": "Select and justify the best response: A treatment improves a biomarker believed to lie on the disease pathway. Prior interventions have changed the same marker without improving survival. Which evidence would most strengthen the claim that the new result represents patient benefit?", "pdf_page": 110, "assessment_id": "q-006-2"}, {"id": "o-006-3", "text": "Select and justify the best response: An efficacy trial of 3,000 participants reports no instances of a serious event thought to occur once per 20,000 exposures. The sponsor calls the event excluded. Which response best matches the trial's information?", "pdf_page": 113, "assessment_id": "q-006-3"}, {"id": "o-006-4", "text": "Select and justify the best response: Assertion (A): A surrogate endpoint may be measured accurately without establishing clinical benefit.\n\nReason (R): Treatment trials can use random allocation to reduce baseline group differences.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 107, "assessment_id": "q-006-4"}, {"id": "o-006-5", "text": "Select and justify the best response: A paper reports a significant 12% biomarker reduction, no difference in recorded symptoms and no mortality follow-up. Which outcome claim can be made directly from these results?", "pdf_page": 107, "assessment_id": "q-006-5"}], "case_ids": ["q-006-1", "q-006-3"]}, {"num": 7, "hook": "A care package fails in a trial. Did its theory fail, or was the package not delivered as intended?", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-007-1", "level": "Essentials", "title": "Why develop and pilot a complex intervention before definitive testing?", "explanation": "To refine components and identify acceptability, feasibility and operational problems.", "pdf_page": 119, "card_id": "fc-007-1"}, {"id": "u-007-2", "level": "Essentials", "title": "What distinguishes core from adaptable components?", "explanation": "Core elements should remain consistent; non-core elements can be adapted to local context based on development work.", "pdf_page": 121, "card_id": "fc-007-2"}, {"id": "u-007-3", "level": "Application", "title": "Why describe the control package in detail?", "explanation": "Otherwise differences may arise from co-interventions, such as human contact, rather than the component being credited.", "pdf_page": 122, "card_id": "fc-007-3"}, {"id": "u-007-4", "level": "Application", "title": "What should a theory of action explain?", "explanation": "How the intervention's components are expected to produce the intended outcomes.", "pdf_page": 122, "card_id": "fc-007-4"}, {"id": "u-007-5", "level": "Deep Dive", "title": "What does a process evaluation investigate?", "explanation": "How implementation occurred, fidelity to the plan, practical barriers and participant or staff experiences.", "pdf_page": 124, "card_id": "fc-007-5"}, {"id": "u-007-6", "level": "Deep Dive", "title": "Why does one negative complex-intervention trial not refute every adaptation?", "explanation": "The package may be poorly optimised or implemented, and effects may depend on setting and component delivery.", "pdf_page": 120, "card_id": "fc-007-6"}], "outcomes": [{"id": "o-007-1", "text": "Select and justify the best response: An intervention arm receives home-monitoring equipment and weekly nurse calls. Controls receive neither. Hospital use is lower in the intervention arm. The proposed claim is that equipment alone reduces admissions. Which additional comparison most directly addresses that claim?", "pdf_page": 122, "assessment_id": "q-007-1"}, {"id": "o-007-2", "text": "Select and justify the best response: A complex programme shows no improvement. Process observations find that half the planned sessions were cancelled and most participants received little of the core content. Which conclusion is best supported?", "pdf_page": 124, "assessment_id": "q-007-2"}, {"id": "o-007-3", "text": "Select and justify the best response: A multisite programme standardises its hypothesised active component while adapting appointment times and materials to local needs. Which development finding would most justify treating those features as adaptable rather than core?", "pdf_page": 121, "assessment_id": "q-007-3"}, {"id": "o-007-4", "text": "Select and justify the best response: Assertion (A): Every component of a complex intervention should be identical across settings.\n\nReason (R): Preserving a core causal mechanism may require adapting some delivery details to context.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 121, "assessment_id": "q-007-4"}, {"id": "o-007-5", "text": "Select and justify the best response: A complex intervention improves confidence but not disease severity. The prespecified outcomes included both. A report calls this a complete failure because severity was unchanged. Which interpretation best retains the outcome structure?", "pdf_page": 123, "assessment_id": "q-007-5"}], "case_ids": ["q-007-1", "q-007-3"]}, {"num": 8, "hook": "A positive test is not a diagnosis by itself. Work out which denominator each accuracy measure uses.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-008-1", "level": "Essentials", "title": "What is sensitivity?", "explanation": "The proportion of people with the target condition who test positive: true positives divided by all with the condition.", "pdf_page": 131, "card_id": "fc-008-1"}, {"id": "u-008-2", "level": "Essentials", "title": "What is specificity?", "explanation": "The proportion without the target condition who test negative: true negatives divided by all without the condition.", "pdf_page": 131, "card_id": "fc-008-2"}, {"id": "u-008-3", "level": "Application", "title": "What does positive predictive value ask?", "explanation": "Among people with a positive result, what proportion truly have the condition? It depends on the population's disease prevalence.", "pdf_page": 133, "card_id": "fc-008-3"}, {"id": "u-008-4", "level": "Application", "title": "Why must the reference standard be independent of the new test?", "explanation": "Including the new test in the reference definition can make validation circular and bias accuracy estimates.", "pdf_page": 135, "card_id": "fc-008-4"}, {"id": "u-008-5", "level": "Deep Dive", "title": "What is verification or work-up bias?", "explanation": "Accuracy is distorted when receipt of the reference standard depends on the index test result, such as verifying positives only.", "pdf_page": 136, "card_id": "fc-008-5"}, {"id": "u-008-6", "level": "Deep Dive", "title": "How is a likelihood ratio used to update diagnostic probability?", "explanation": "Convert pre-test probability to odds, multiply by the appropriate likelihood ratio, then convert post-test odds to probability.", "pdf_page": 139, "card_id": "fc-008-6"}], "outcomes": [{"id": "o-008-1", "text": "Select and justify the best response: A new diagnostic test is evaluated using only clear-cut severe cases and healthy volunteers. The intended clinic population mostly has borderline symptoms and competing diagnoses. Which change most directly improves the relevance of the validation?", "pdf_page": 135, "assessment_id": "q-008-1"}, {"id": "o-008-2", "text": "Select and justify the best response: Only index-test-positive patients receive the reference procedure. Index-test-negative patients are classified as disease-free without verification. Which reported performance feature is most directly undermined by this design?", "pdf_page": 136, "assessment_id": "q-008-2"}, {"id": "o-008-3", "text": "Select and justify the best response: The new index test contributes to the reference diagnosis against which its accuracy is measured. The index result is interpreted reproducibly and the sample is large. Which modification most directly improves the validity of the comparison?", "pdf_page": 135, "assessment_id": "q-008-3"}, {"id": "o-008-4", "text": "Select and justify the best response: Assertion (A): A positive predictive value of 90% means the test identifies 90% of people who have the disease.\n\nReason (R): Positive predictive value uses all positive index-test results as its denominator.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 133, "assessment_id": "q-008-4"}, {"id": "o-008-5", "text": "Select and justify the best response: Before testing, disease probability is 20%. The likelihood ratio for the observed result is 4. Assuming this LR applies to the patient, what is the post-test probability?", "pdf_page": 139, "assessment_id": "q-008-5"}], "case_ids": ["q-008-1", "q-008-3"]}, {"num": 9, "hook": "A polished pooled estimate can hide inconsistent studies. Inspect the review process before the diamond.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-009-1", "level": "Essentials", "title": "Why can a narrative selection of supportive studies mislead?", "explanation": "Selective inclusion may reflect the reviewer's prior beliefs rather than the full eligible evidence.", "pdf_page": 148, "card_id": "fc-009-1"}, {"id": "u-009-2", "level": "Essentials", "title": "Why define a review question precisely before selecting papers?", "explanation": "It supports explicit, reproducible inclusion decisions about population, intervention, comparison and outcome.", "pdf_page": 151, "card_id": "fc-009-2"}, {"id": "u-009-3", "level": "Application", "title": "Why appraise risk of bias in included studies?", "explanation": "Pooling does not remove weaknesses of primary studies, and composite quality scores can obscure important differences.", "pdf_page": 154, "card_id": "fc-009-3"}, {"id": "u-009-4", "level": "Application", "title": "What is meta-analysis?", "explanation": "Statistical synthesis of numerical results from several studies addressing the same question, when combining them is appropriate.", "pdf_page": 156, "card_id": "fc-009-4"}, {"id": "u-009-5", "level": "Deep Dive", "title": "What does a forest plot show?", "explanation": "Individual study effects and uncertainty alongside an overall estimate; interpret the effect scale and no-effect line.", "pdf_page": 158, "card_id": "fc-009-5"}, {"id": "u-009-6", "level": "Deep Dive", "title": "What is heterogeneity in a review?", "explanation": "Differences among study results that require examination of clinical, methodological and statistical explanations.", "pdf_page": 161, "card_id": "fc-009-6"}], "outcomes": [{"id": "o-009-1", "text": "Select and justify the best response: A review team excludes trials after seeing that their effects run opposite to its expected result, although they meet the question and quality criteria. The team cites reduced heterogeneity as justification. Which principle should govern inclusion?", "pdf_page": 151, "assessment_id": "q-009-1"}, {"id": "o-009-2", "text": "Select and justify the best response: A meta-analysis combines trials with different populations, intervention intensity and follow-up. Their effects differ substantially. Which next analysis most directly helps interpret the inconsistency before recommending one pooled effect?", "pdf_page": 161, "assessment_id": "q-009-2"}, {"id": "o-009-3", "text": "Select and justify the best response: A review assigns every trial a total quality score. Trial X scores well overall but has a serious allocation problem. The review treats it as low risk because its total exceeds the cut-off. Which concern most directly challenges this classification?", "pdf_page": 154, "assessment_id": "q-009-3"}, {"id": "o-009-4", "text": "Select and justify the best response: Assertion (A): A systematic review can be methodologically rigorous without calculating a pooled numerical effect.\n\nReason (R): A meta-analysis is the statistical combination of numerical study results.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 156, "assessment_id": "q-009-4"}, {"id": "o-009-5", "text": "Select and justify the best response: In a forest plot of risk ratios, a small study has RR 0.60 with CI 0.20–1.80; a larger study has RR 0.85 with CI 0.76–0.95. Which interpretation best uses both effect and uncertainty?", "pdf_page": 158, "assessment_id": "q-009-5"}], "case_ids": ["q-009-1", "q-009-3"]}, {"num": 10, "hook": "A recommendation is only useful if its evidence, development and fit with real care are credible.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-010-1", "level": "Essentials", "title": "What three broad aspects of a guideline deserve appraisal?", "explanation": "Its content, the process used to develop it, and how it is presented to intended users.", "pdf_page": 174, "card_id": "fc-010-1"}, {"id": "u-010-2", "level": "Essentials", "title": "What does stakeholder involvement in guideline appraisal include?", "explanation": "Relevant professionals, views and preferences of the target population, and clearly identified intended users.", "pdf_page": 175, "card_id": "fc-010-2"}, {"id": "u-010-3", "level": "Application", "title": "Why inspect conflicts of interest in guideline development?", "explanation": "Financial and professional commitments can influence which problems are framed and which options are favoured.", "pdf_page": 176, "card_id": "fc-010-3"}, {"id": "u-010-4", "level": "Application", "title": "What expertise should a guideline panel draw on?", "explanation": "Topic expertise, evidence-methods expertise and the experience of people affected by the condition.", "pdf_page": 177, "card_id": "fc-010-4"}, {"id": "u-010-5", "level": "Deep Dive", "title": "How should a recommendation connect to evidence?", "explanation": "Through a transparent search and appraisal of relevant research, with uncertainty and evidence strength made clear.", "pdf_page": 178, "card_id": "fc-010-5"}, {"id": "u-010-6", "level": "Deep Dive", "title": "Why assess patient acceptability and practical feasibility?", "explanation": "An apparently sound recommendation may be unaffordable, burdensome or unacceptable to the people expected to follow it.", "pdf_page": 180, "card_id": "fc-010-6"}], "outcomes": [{"id": "o-010-1", "text": "Select and justify the best response: A guideline panel has strong subject expertise but no methods specialist or patient representative. Its recommendations concern burdensome long-term treatment. Which addition most directly addresses the missing perspectives?", "pdf_page": 177, "assessment_id": "q-010-1"}, {"id": "o-010-2", "text": "Select and justify the best response: A guideline transparently describes a comprehensive search but gives no account of study appraisal or how findings became recommendations. What is the most important unresolved link?", "pdf_page": 178, "assessment_id": "q-010-2"}, {"id": "o-010-3", "text": "Select and justify the best response: A guideline favours a product sold by its main funder. Several recommendations are reasonable and supported by trials. Which appraisal response is best justified?", "pdf_page": 176, "assessment_id": "q-010-3"}, {"id": "o-010-4", "text": "Select and justify the best response: Assertion (A): A guideline with a rigorous development process can still be difficult to use in practice.\n\nReason (R): Presentation and practical usability are aspects of guideline appraisal in addition to content and development.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 174, "assessment_id": "q-010-4"}, {"id": "o-010-5", "text": "Select and justify the best response: A recommendation offers a small average benefit at the cost of frequent travel. The patient values independence but cannot reliably reach the clinic. Which information would most improve the guideline's practical application?", "pdf_page": 180, "assessment_id": "q-010-5"}], "case_ids": ["q-010-1", "q-010-3"]}, {"num": 11, "hook": "The cheapest option and the best value option may differ. Ask whose costs count and what extra benefit is purchased.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-011-1", "level": "Essentials", "title": "When is cost-minimisation analysis appropriate?", "explanation": "When compared interventions have equivalent outcomes; otherwise simply choosing the cheapest can mislead.", "pdf_page": 184, "card_id": "fc-011-1"}, {"id": "u-011-2", "level": "Essentials", "title": "Why use economic modelling in addition to a single trial?", "explanation": "A model can compare more options and longer-term consequences, but its assumptions and input evidence need appraisal.", "pdf_page": 186, "card_id": "fc-011-2"}, {"id": "u-011-3", "level": "Application", "title": "What does a quality-adjusted life-year combine?", "explanation": "Time lived and a preference-based quality weight for that health state; the valuation method and whose values are used matter.", "pdf_page": 188, "card_id": "fc-011-3"}, {"id": "u-011-4", "level": "Application", "title": "What does an incremental cost-effectiveness ratio compare?", "explanation": "The difference in costs divided by the difference in effects between alternatives, rather than their separate average ratios.", "pdf_page": 189, "card_id": "fc-011-4"}, {"id": "u-011-5", "level": "Deep Dive", "title": "Why state an economic evaluation's perspective?", "explanation": "It determines whose costs and benefits are included, such as the health service, patient or society.", "pdf_page": 192, "card_id": "fc-011-5"}, {"id": "u-011-6", "level": "Deep Dive", "title": "Why perform a sensitivity analysis?", "explanation": "To see whether reasonable changes in uncertain assumptions or inputs change the economic conclusion.", "pdf_page": 194, "card_id": "fc-011-6"}], "outcomes": [{"id": "o-011-1", "text": "Select and justify the best response: A hospital compares two treatments. Their clinical outcomes have not been shown equivalent, but one costs less. The analyst proposes cost-minimisation as the deciding method. Which objection most directly addresses the choice of method?", "pdf_page": 184, "assessment_id": "q-011-1"}, {"id": "o-011-2", "text": "Select and justify the best response: An economic evaluation adopts a health-service perspective. A second analysis includes patient travel and lost work time and reaches a different conclusion. Which explanation is most defensible?", "pdf_page": 192, "assessment_id": "q-011-2"}, {"id": "o-011-3", "text": "Select and justify the best response: A model favours programme A under its central assumptions. A plausible change in the duration of benefit makes programme B preferable. What is the most useful interpretation for a policymaker?", "pdf_page": 194, "assessment_id": "q-011-3"}, {"id": "o-011-4", "text": "Select and justify the best response: Assertion (A): An incremental cost-effectiveness ratio is calculated by dividing the new intervention’s total cost by its total effect.\n\nReason (R): Incremental analysis compares differences in cost and effect between alternatives.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 189, "assessment_id": "q-011-4"}, {"id": "o-011-5", "text": "Select and justify the best response: A new programme costs £1,200 per patient and produces 0.80 QALY; usual care costs £1,000 and produces 0.75 QALY over the same horizon. What is the incremental cost per additional QALY?", "pdf_page": 194, "assessment_id": "q-011-5"}], "case_ids": ["q-011-1", "q-011-3"]}, {"num": 12, "hook": "Numbers show a pattern; interviews may explain how people experience it. Apply standards that fit the question.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-012-1", "level": "Essentials", "title": "What kinds of material can qualitative research analyse?", "explanation": "Interviews, observations, documents and other meaning-rich data to develop explanations and understanding.", "pdf_page": 200, "card_id": "fc-012-1"}, {"id": "u-012-2", "level": "Essentials", "title": "What is reflexivity?", "explanation": "Explicit consideration of how the researcher's perspective and role may shape data collection, interpretation and claims.", "pdf_page": 201, "card_id": "fc-012-2"}, {"id": "u-012-3", "level": "Application", "title": "What is triangulation?", "explanation": "Bringing more than one method or perspective to bear on a question to enrich and test interpretation.", "pdf_page": 201, "card_id": "fc-012-3"}, {"id": "u-012-4", "level": "Application", "title": "What is progressive focusing?", "explanation": "Refining the research question and methods as emerging findings clarify what needs investigation.", "pdf_page": 202, "card_id": "fc-012-4"}, {"id": "u-012-5", "level": "Deep Dive", "title": "Why use purposive sampling?", "explanation": "To seek relevant and contrasting experiences that illuminate the question, rather than merely estimate an average population value.", "pdf_page": 205, "card_id": "fc-012-5"}, {"id": "u-012-6", "level": "Deep Dive", "title": "Why actively examine contradictory or negative cases?", "explanation": "A defensible analysis must test and refine explanations rather than cherry-pick appealing quotations.", "pdf_page": 207, "card_id": "fc-012-6"}], "outcomes": [{"id": "o-012-1", "text": "Select and justify the best response: Researchers seek to explain why some patients find a service accessible and others avoid it. They deliberately recruit contrasting users and non-users, rather than a random sample of current attenders. Which appraisal criterion best fits this choice?", "pdf_page": 205, "assessment_id": "q-012-1"}, {"id": "o-012-2", "text": "Select and justify the best response: A qualitative team develops a theory from interviews. Several accounts contradict it. Which analytic response most strengthens the explanatory work?", "pdf_page": 207, "assessment_id": "q-012-2"}, {"id": "o-012-3", "text": "Select and justify the best response: An interviewer is also a clinician in the service being studied. The report describes how this role affected recruitment, questioning and interpretation. What can a reader reasonably infer from this account?", "pdf_page": 206, "assessment_id": "q-012-3"}, {"id": "o-012-4", "text": "Select and justify the best response: Assertion (A): Triangulation refers to combining methods or perspectives to examine a phenomenon.\n\nReason (R): Reflexivity involves considering how the researcher’s perspective may influence interpretation.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 201, "assessment_id": "q-012-4"}, {"id": "o-012-5", "text": "Select and justify the best response: A paper reports “analysis was performed in NVivo”, includes three vivid quotations and gives no description of coding, comparison or contradictory cases. What is the most consequential reporting gap?", "pdf_page": 208, "assessment_id": "q-012-5"}], "case_ids": ["q-012-1", "q-012-3"]}, {"num": 13, "hook": "A questionnaire is easy to distribute. A valid inference depends on what it measures and who answers.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-013-1", "level": "Essentials", "title": "Is a questionnaire intrinsically quantitative or qualitative?", "explanation": "Neither; the questions and response formats determine the types of data collected.", "pdf_page": 215, "card_id": "fc-013-1"}, {"id": "u-013-2", "level": "Essentials", "title": "Why look for a suitable previously validated instrument?", "explanation": "It can save development work, enable comparisons and provide prior measurement evidence; suitability for the current use still matters.", "pdf_page": 217, "card_id": "fc-013-2"}, {"id": "u-013-3", "level": "Application", "title": "How do validity and reliability differ?", "explanation": "Validity concerns measuring the intended construct; reliability concerns consistency of measurement.", "pdf_page": 218, "card_id": "fc-013-3"}, {"id": "u-013-4", "level": "Application", "title": "What instructions help participants answer appropriately?", "explanation": "Explain purpose, confidentiality, voluntariness, contact details and how to complete each item.", "pdf_page": 219, "card_id": "fc-013-4"}, {"id": "u-013-5", "level": "Deep Dive", "title": "Why can an opening-hours survey of current clinic attenders mislead?", "explanation": "People unable to attend at those hours are systematically missing from the sample.", "pdf_page": 221, "card_id": "fc-013-5"}, {"id": "u-013-6", "level": "Deep Dive", "title": "Why pilot a questionnaire?", "explanation": "To identify problems in wording, layout and completion before the main survey and improve its practical usability.", "pdf_page": 222, "card_id": "fc-013-6"}], "outcomes": [{"id": "o-013-1", "text": "Select and justify the best response: A questionnaire gives very similar scores on repeat administration but its items focus on clinic convenience when the claimed construct is treatment effectiveness. What is the best interpretation of the measurement evidence?", "pdf_page": 218, "assessment_id": "q-013-1"}, {"id": "o-013-2", "text": "Select and justify the best response: An opening-hours survey recruits people attending a morning clinic. Most report that mornings are convenient. The intended inference concerns everyone registered with the practice. Which missing group is most likely to alter the interpretation?", "pdf_page": 221, "assessment_id": "q-013-2"}, {"id": "o-013-3", "text": "Select and justify the best response: A team adapts a previously validated questionnaire for a different language and patient group, changing several response categories. Which claim now needs particular justification?", "pdf_page": 217, "assessment_id": "q-013-3"}, {"id": "o-013-4", "text": "Select and justify the best response: Assertion (A): Reliability demonstrates that a questionnaire measures the intended construct.\n\nReason (R): A larger response sample automatically corrects systematic misunderstanding of an item.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 218, "assessment_id": "q-013-4"}, {"id": "o-013-5", "text": "Select and justify the best response: A survey receives 180 responses from 200 invitations in clinic A and 60 from 200 in clinic B. Most non-responders in B cannot use the online form. Which comparison is most defensible before pooling satisfaction scores?", "pdf_page": 222, "assessment_id": "q-013-5"}], "case_ids": ["q-013-1", "q-013-3"]}, {"num": 14, "hook": "A service improves after a pathway is introduced. Did the pathway cause the improvement?", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-014-1", "level": "Essentials", "title": "What does context mean in quality improvement?", "explanation": "The local organisational and real-world conditions in which a change is introduced.", "pdf_page": 230, "card_id": "fc-014-1"}, {"id": "u-014-2", "level": "Essentials", "title": "Why make the mechanism of improvement explicit?", "explanation": "It explains how a proposed change is expected to improve care and helps interpret success or failure.", "pdf_page": 231, "card_id": "fc-014-2"}, {"id": "u-014-3", "level": "Application", "title": "Why define success before evaluating an initiative?", "explanation": "Without specified outcomes and reasonable measurement, claims of improvement are difficult to assess.", "pdf_page": 232, "card_id": "fc-014-3"}, {"id": "u-014-4", "level": "Application", "title": "Why report the change process in detail?", "explanation": "Who did what, how and under what constraints helps others interpret outcomes and transfer lessons.", "pdf_page": 233, "card_id": "fc-014-4"}, {"id": "u-014-5", "level": "Deep Dive", "title": "What is the Hawthorne effect relevant to quality improvement?", "explanation": "Performance can change because staff receive attention or know a change is being studied, not solely because of its intrinsic content.", "pdf_page": 234, "card_id": "fc-014-5"}, {"id": "u-014-6", "level": "Deep Dive", "title": "What distinguishes local improvement from a broader research claim?", "explanation": "Research claims need justified lessons transferable beyond the local site, with context and limitations explained.", "pdf_page": 236, "card_id": "fc-014-6"}], "outcomes": [{"id": "o-014-1", "text": "Select and justify the best response: After a care pathway is introduced, length of stay falls. During the same period the hospital also opens a discharge lounge and changes senior staffing. Which claim is best supported by an uncontrolled before-and-after comparison?", "pdf_page": 234, "assessment_id": "q-014-1"}, {"id": "o-014-2", "text": "Select and justify the best response: An improvement team wants to show that a new triage process works. Before implementation it writes “success means a better service” but chooses no measure. Which revision most improves the evaluability of the project?", "pdf_page": 232, "assessment_id": "q-014-2"}, {"id": "o-014-3", "text": "Select and justify the best response: A quality-improvement report gives outcome changes but little account of how the pathway was delivered. A second hospital wants to know whether a similar approach would work there. Which additional information would most directly improve that judgement?", "pdf_page": 233, "assessment_id": "q-014-3"}, {"id": "o-014-4", "text": "Select and justify the best response: Assertion (A): A plausible theory of change establishes that the intended improvement occurred.\n\nReason (R): Outcome measurement can be omitted when staff agree that care improved.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 231, "assessment_id": "q-014-4"}, {"id": "o-014-5", "text": "Select and justify the best response: A local project reports a shorter stay after implementation and recommends that every hospital copy the pathway unchanged. Which additional evidence most directly strengthens the transferable lesson?", "pdf_page": 236, "assessment_id": "q-014-5"}], "case_ids": ["q-014-1", "q-014-3"]}, {"num": 15, "hook": "Separate genetic association, causation, prediction and usefulness for an individual.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-015-1", "level": "Essentials", "title": "What is a genome-wide association study?", "explanation": "A large observational study comparing genomic variants in relation to traits or disease, often using cohort or case-control designs.", "pdf_page": 241, "card_id": "fc-015-1"}, {"id": "u-015-2", "level": "Essentials", "title": "Why is a disease-associated SNP not automatically causal?", "explanation": "It can mark an associated genomic region without itself being the causal variant; biological plausibility needs further investigation.", "pdf_page": 243, "card_id": "fc-015-2"}, {"id": "u-015-3", "level": "Application", "title": "Does a risk-associated variant predict inevitable disease?", "explanation": "No. Many associations are weak and probabilistic, so an association is not a deterministic individual prediction.", "pdf_page": 244, "card_id": "fc-015-3"}, {"id": "u-015-4", "level": "Application", "title": "Why do observational quality checks still matter in GWAS?", "explanation": "Case and control selection, population differences, confounding and measurement can still distort high-technology studies.", "pdf_page": 250, "card_id": "fc-015-4"}, {"id": "u-015-5", "level": "Deep Dive", "title": "Why define phenotypes precisely?", "explanation": "Inconsistent or unclear disease and trait definitions can undermine genetic association analyses.", "pdf_page": 251, "card_id": "fc-015-5"}, {"id": "u-015-6", "level": "Deep Dive", "title": "What is the winner's curse?", "explanation": "Initially detected associations can have inflated effect estimates because larger apparent effects more readily cross significance thresholds.", "pdf_page": 252, "card_id": "fc-015-6"}], "outcomes": [{"id": "o-015-1", "text": "Select and justify the best response: A genome-wide study identifies a SNP associated with a disease. The SNP lies near a biologically plausible gene, but no functional work has tested the variant. Which next finding most directly strengthens a causal interpretation of this variant itself?", "pdf_page": 243, "assessment_id": "q-015-1"}, {"id": "o-015-2", "text": "Select and justify the best response: Cases are recruited from a specialist clinic and controls from a community database. The groups also differ in ancestry. A small association is reported between a variant and disease. Which check most directly addresses a plausible non-causal explanation?", "pdf_page": 250, "assessment_id": "q-015-2"}, {"id": "o-015-3", "text": "Select and justify the best response: A discovery study reports a large variant effect just beyond its significance threshold. A well-designed replication estimates a smaller effect in the same direction. Which interpretation is most defensible before examining further evidence?", "pdf_page": 252, "assessment_id": "q-015-3"}, {"id": "o-015-4", "text": "Select and justify the best response: Assertion (A): Using a precise, standardised phenotype definition helps make genetic associations interpretable.\n\nReason (R): A highly significant association establishes which nearby gene variant is causal.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 251, "assessment_id": "q-015-4"}, {"id": "o-015-5", "text": "Select and justify the best response: A variant is associated with a disease at OR 1.15. A report tells a carrier that the disease is likely to develop. Baseline risk and individual predictive performance are not supplied. Which missing information most directly limits that individual prediction?", "pdf_page": 244, "assessment_id": "q-015-5"}], "case_ids": ["q-015-1", "q-015-3"]}, {"num": 16, "hook": "Similar risks can lead to different reasonable choices when priorities differ.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-016-1", "level": "Essentials", "title": "How do patient narrative and research evidence relate?", "explanation": "They can complement one another: population evidence informs care while the patient's story and clinical judgement give individual meaning.", "pdf_page": 257, "card_id": "fc-016-1"}, {"id": "u-016-2", "level": "Essentials", "title": "What are patient-reported outcome measures?", "explanation": "Instruments collecting outcomes directly from patients, intended to capture aspects of health that matter to them.", "pdf_page": 258, "card_id": "fc-016-2"}, {"id": "u-016-3", "level": "Application", "title": "What does shared decision-making support?", "explanation": "A supported deliberation between clinician and patient about evidence, options, uncertainty and the patient's priorities.", "pdf_page": 259, "card_id": "fc-016-3"}, {"id": "u-016-4", "level": "Application", "title": "What is an option grid designed to do?", "explanation": "Support a focused comparison and conversation about options using questions important to patients.", "pdf_page": 262, "card_id": "fc-016-4"}, {"id": "u-016-5", "level": "Deep Dive", "title": "Why does an option grid need conversation?", "explanation": "Its purpose is option talk and deliberation, not merely handing over information.", "pdf_page": 263, "card_id": "fc-016-5"}, {"id": "u-016-6", "level": "Deep Dive", "title": "What practical limitation can affect n-of-1 trials?", "explanation": "Repeated switches and trial participation may be burdensome; people may prefer to continue an option they feel works.", "pdf_page": 265, "card_id": "fc-016-6"}], "outcomes": [{"id": "o-016-1", "text": "Select and justify the best response: A clinician accurately explains absolute benefit and harm, then asks a patient to choose without discussing how the options fit the patient's life. The patient asks for help deciding. Which next step best advances shared decision-making?", "pdf_page": 259, "assessment_id": "q-016-1"}, {"id": "o-016-2", "text": "Select and justify the best response: Two clinicians use the same option grid. One reads the preferred recommendation aloud and files the sheet. The other uses patient questions to compare options and discuss trade-offs. Which feature most directly distinguishes the second use?", "pdf_page": 263, "assessment_id": "q-016-2"}, {"id": "o-016-3", "text": "Select and justify the best response: A service introduces a patient-reported function scale after surgery. Surgeons' ratings improve, but patient scores remain unchanged. Which first response best addresses the discrepancy?", "pdf_page": 258, "assessment_id": "q-016-3"}, {"id": "o-016-4", "text": "Select and justify the best response: Assertion (A): Similar population benefit estimates can support different choices for two patients.\n\nReason (R): The two patients may attach different importance to the outcomes and treatment burdens.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 257, "assessment_id": "q-016-4"}, {"id": "o-016-5", "text": "Select and justify the best response: In an n-of-1 crossover exercise, a participant feels much better on one treatment and declines further switches. Researchers want both a valid comparison and an acceptable process. Which issue should be explicitly addressed?", "pdf_page": 265, "assessment_id": "q-016-5"}], "case_ids": ["q-016-1", "q-016-3"]}, {"num": 17, "hook": "An algorithm performs well in a dataset. Will it improve care in your setting?", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-017-1", "level": "Essentials", "title": "What distinguishes machine learning from fixed rules?", "explanation": "Algorithms learn patterns from data rather than relying solely on explicitly programmed decision rules.", "pdf_page": 273, "card_id": "fc-017-1"}, {"id": "u-017-2", "level": "Essentials", "title": "Why check fluent generative-AI output?", "explanation": "Conversational fluency and apparent confidence do not establish factual correctness or clinical reliability.", "pdf_page": 274, "card_id": "fc-017-2"}, {"id": "u-017-3", "level": "Application", "title": "What is the first practical AI appraisal question?", "explanation": "Its intended use, intended users, target patients and relevance to the clinical problem.", "pdf_page": 279, "card_id": "fc-017-3"}, {"id": "u-017-4", "level": "Application", "title": "What should be reported about AI input data?", "explanation": "Their source, acquisition, preprocessing, quality and handling of missing or poor-quality inputs.", "pdf_page": 281, "card_id": "fc-017-4"}, {"id": "u-017-5", "level": "Deep Dive", "title": "Why is AI safety assessment continuous?", "explanation": "Risks can emerge before, during and after implementation; changes and observed harms need reporting.", "pdf_page": 282, "card_id": "fc-017-5"}, {"id": "u-017-6", "level": "Deep Dive", "title": "Why might study performance not transfer to practice?", "explanation": "Local patients, workflow and implementation may differ from the training and evaluation setting.", "pdf_page": 277, "card_id": "fc-017-6"}], "outcomes": [{"id": "o-017-1", "text": "Select and justify the best response: An AI model performs well retrospectively at its development hospital. A clinic with different patients and a different care pathway wants to use it for triage. Which evidence most directly addresses the clinic's adoption question?", "pdf_page": 277, "assessment_id": "q-017-1"}, {"id": "o-017-2", "text": "Select and justify the best response: A model paper reports a high aggregate performance score but omits data sources, preprocessing and treatment of missing values. Which first request best supports an appraisal of how the result was produced?", "pdf_page": 281, "assessment_id": "q-017-2"}, {"id": "o-017-3", "text": "Select and justify the best response: A clinical AI system is modified after deployment. Early evaluation recorded no safety incidents. Which response most appropriately follows from the change and initial evidence?", "pdf_page": 282, "assessment_id": "q-017-3"}, {"id": "o-017-4", "text": "Select and justify the best response: Assertion (A): A fluent clinical answer establishes that the underlying claims are accurate.\n\nReason (R): A conversational system can produce plausible statements that are unsupported or incorrect.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 274, "assessment_id": "q-017-4"}, {"id": "o-017-5", "text": "Select and justify the best response: An AI paper reports excellent image-classification performance but does not specify the clinical decision, intended users or care pathway. The clinic must decide whether to adopt it. Which missing comparison is the priority for that adoption decision?", "pdf_page": 279, "assessment_id": "q-017-5"}], "case_ids": ["q-017-1", "q-017-3"]}, {"num": 18, "hook": "Explain how and why an intervention acts, alongside estimating whether it works.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-018-1", "level": "Essentials", "title": "What is mechanistic evidence?", "explanation": "Evidence about the causal process through which an intervention or exposure produces an effect.", "pdf_page": 287, "card_id": "fc-018-1"}, {"id": "u-018-2", "level": "Essentials", "title": "How can mechanisms explain a failed feeding programme?", "explanation": "Food may not be eaten, absorbed or delivered as expected; local biological and social pathways can block effects.", "pdf_page": 288, "card_id": "fc-018-2"}, {"id": "u-018-3", "level": "Application", "title": "Are mechanistic studies equally strong?", "explanation": "No. Their quality and contribution to a coherent causal explanation need appraisal; a simple hierarchy is insufficient.", "pdf_page": 289, "card_id": "fc-018-3"}, {"id": "u-018-4", "level": "Application", "title": "How do mechanisms and probabilistic evidence contribute together?", "explanation": "They address complementary aspects of causal inference, including observed associations and causal pathways.", "pdf_page": 290, "card_id": "fc-018-4"}, {"id": "u-018-5", "level": "Deep Dive", "title": "What does EBM+ add to appraisal?", "explanation": "Consider mechanistic alongside probabilistic evidence rather than treating either as a universal substitute.", "pdf_page": 291, "card_id": "fc-018-5"}, {"id": "u-018-6", "level": "Deep Dive", "title": "Why distinguish advice from actual exposure?", "explanation": "If advice does not change behaviour, its effect does not establish the effect of consistently receiving the intervention.", "pdf_page": 294, "card_id": "fc-018-6"}], "outcomes": [{"id": "o-018-1", "text": "Select and justify the best response: A feeding programme uses nutritionally balanced meals but shows no growth effect. Observation finds that many children reject the unfamiliar food. Which inference best combines the outcome and process evidence?", "pdf_page": 288, "assessment_id": "q-018-1"}, {"id": "o-018-2", "text": "Select and justify the best response: A proposed mechanism is supported at its first and final stages, but the connecting biological step is weakly evidenced. Several studies repeat the same initial observation. Which appraisal best addresses the causal account?", "pdf_page": 289, "assessment_id": "q-018-2"}, {"id": "o-018-3", "text": "Select and justify the best response: A trial suggests benefit but the proposed mechanism is uncertain. A laboratory study supports one causal pathway but cannot estimate clinical benefit. Which next synthesis is most appropriate?", "pdf_page": 291, "assessment_id": "q-018-3"}, {"id": "o-018-4", "text": "Select and justify the best response: Assertion (A): Mechanistic evidence is confined to molecular laboratory experiments.\n\nReason (R): A plausible mechanism alone establishes the size of an intervention’s clinical effect.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 290, "assessment_id": "q-018-4"}, {"id": "o-018-5", "text": "Select and justify the best response: A trial randomises advice to adopt a behaviour. Uptake is 25%, and the intention-to-advise comparison shows no clear benefit. Which claim is closest to what was tested?", "pdf_page": 294, "assessment_id": "q-018-5"}], "case_ids": ["q-018-1", "q-018-3"]}, {"num": 19, "hook": "Experts agree. Ask who participated, how agreement was defined and whose disagreement remains.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-019-1", "level": "Essentials", "title": "What are four key Delphi characteristics?", "explanation": "Anonymity, iteration, feedback and statistical analysis of responses.", "pdf_page": 303, "card_id": "fc-019-1"}, {"id": "u-019-2", "level": "Essentials", "title": "How does nominal group technique broaden participation?", "explanation": "Structured individual idea generation and turn-taking reduce domination of initial contributions by outspoken people.", "pdf_page": 302, "card_id": "fc-019-2"}, {"id": "u-019-3", "level": "Application", "title": "What expertise can enrich a consensus panel?", "explanation": "Research-methods, clinical and lived-experience expertise, with relevant perspectives represented.", "pdf_page": 306, "card_id": "fc-019-3"}, {"id": "u-019-4", "level": "Application", "title": "Why describe and justify the consensus method?", "explanation": "Readers need to judge fit with the question, modifications and the definition of consensus.", "pdf_page": 307, "card_id": "fc-019-4"}, {"id": "u-019-5", "level": "Deep Dive", "title": "Why examine stability between Delphi rounds?", "explanation": "It shows whether agreement or disagreement persists or changes and can identify enduring tensions.", "pdf_page": 308, "card_id": "fc-019-5"}, {"id": "u-019-6", "level": "Deep Dive", "title": "Why report dissent?", "explanation": "Minority views and their reasons may matter to decisions; agreement percentages can conceal substantive disagreement.", "pdf_page": 309, "card_id": "fc-019-6"}], "outcomes": [{"id": "o-019-1", "text": "Select and justify the best response: A consensus panel addresses treatment burden but includes only researchers who developed the intervention. The authors report a high agreement percentage. Which issue most directly limits interpretation of the agreement's scope?", "pdf_page": 306, "assessment_id": "q-019-1"}, {"id": "o-019-2", "text": "Select and justify the best response: A Delphi study sets consensus at 80% agreement. After seeing the results, it lowers the threshold to 65% so several desired statements qualify. Which concern is most direct?", "pdf_page": 307, "assessment_id": "q-019-2"}, {"id": "o-019-3", "text": "Select and justify the best response: A group wants to explore expert views while reducing direct pressure from senior speakers. Which feature of a Delphi process most directly serves that purpose?", "pdf_page": 303, "assessment_id": "q-019-3"}, {"id": "o-019-4", "text": "Select and justify the best response: Assertion (A): A consensus report can be useful while retaining and explaining minority disagreement.\n\nReason (R): A majority agreement percentage shows that the dissenting reasons are factually incorrect.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 309, "assessment_id": "q-019-4"}, {"id": "o-019-5", "text": "Select and justify the best response: Two Delphi rounds both report 75% agreement. The identities of agreeing and disagreeing participants change markedly between rounds. What should be checked before calling the responses stable?", "pdf_page": 308, "assessment_id": "q-019-5"}], "case_ids": ["q-019-1", "q-019-3"]}, {"num": 20, "hook": "Whose questions, values and knowledge are represented in the evidence system?", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 25, "units": [{"id": "u-020-1", "level": "Essentials", "title": "How can poor evidence-based practice fail its own aims?", "explanation": "By treating numbers uncritically, imposing rigid protocols or disregarding patients rather than applying evidence thoughtfully.", "pdf_page": 313, "card_id": "fc-020-1"}, {"id": "u-020-2", "level": "Essentials", "title": "Why is missing trial evidence not proof that a need is unimportant?", "explanation": "Published research does not map perfectly onto patient needs or all forms of useful knowledge.", "pdf_page": 314, "card_id": "fc-020-2"}, {"id": "u-020-3", "level": "Application", "title": "What concern accompanies excessive standardisation?", "explanation": "Rules can impose unjustified control and fail to reflect clinical complexity.", "pdf_page": 315, "card_id": "fc-020-3"}, {"id": "u-020-4", "level": "Application", "title": "Why can an average effect miss an individual's priorities?", "explanation": "The patient's experience is a complex story that may not fit a population average or one utility score.", "pdf_page": 316, "card_id": "fc-020-4"}, {"id": "u-020-5", "level": "Deep Dive", "title": "Why can accumulating guidelines create problems?", "explanation": "The volume of recommendations can exceed what clinicians can absorb or use appropriately in a consultation.", "pdf_page": 317, "card_id": "fc-020-5"}, {"id": "u-020-6", "level": "Deep Dive", "title": "Why does policy require more than evidence of what works?", "explanation": "Decisions involve values, priorities, context and socially agreed goals as well as effects.", "pdf_page": 319, "card_id": "fc-020-6"}], "outcomes": [{"id": "o-020-1", "text": "Select and justify the best response: An organisation prioritises a condition because several RCTs exist, while dismissing a serious unmet need with little trial evidence. Which assumption most directly deserves challenge?", "pdf_page": 314, "assessment_id": "q-020-1"}, {"id": "o-020-2", "text": "Select and justify the best response: Two policies have well-estimated effects. One yields more total benefit; the other distributes a smaller benefit more equally. Analysts agree on the estimates but disagree on which to choose. Which additional work most directly addresses the disagreement?", "pdf_page": 319, "assessment_id": "q-020-2"}, {"id": "o-020-3", "text": "Select and justify the best response: A decision model favours treatment because of its average health gain. A patient values avoiding dependence on daily care and describes burdens not represented in the model. Which response best engages the limitation?", "pdf_page": 316, "assessment_id": "q-020-3"}, {"id": "o-020-4", "text": "Select and justify the best response: Assertion (A): Some limitations of evidence-based healthcare remain even when individual studies are appraised well.\n\nReason (R): Clinical and policy decisions also involve context, competing values and forms of knowledge not exhausted by study estimates.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 315, "assessment_id": "q-020-4"}, {"id": "o-020-5", "text": "Select and justify the best response: A clinician receives many individually evidence-based prompts during a short consultation. Completing each would leave no time for the patient's main concern. Which evaluation best addresses whether the prompting strategy improves care overall?", "pdf_page": 317, "assessment_id": "q-020-5"}], "case_ids": ["q-020-1", "q-020-3"]}, {"num": 21, "hook": "Use checklists to prompt judgement, then record what is known, uncertain and relevant.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 15, "units": [{"id": "u-021-1", "level": "Essentials", "title": "What begins a context-sensitive evidence-based encounter?", "explanation": "Identify and prioritise clinical, psychological, social and other concerns, including the patient's perspective.", "pdf_page": 323, "card_id": "fc-021-1"}, {"id": "u-021-2", "level": "Essentials", "title": "What determines the search strategy in the checklist?", "explanation": "Whether the purpose is browsing, a focused answer or a comprehensive review.", "pdf_page": 324, "card_id": "fc-021-2"}, {"id": "u-021-3", "level": "Application", "title": "How should design be judged in general appraisal?", "explanation": "Against the research question and field, alongside ethics and governance.", "pdf_page": 325, "card_id": "fc-021-3"}, {"id": "u-021-4", "level": "Application", "title": "What should be considered before accepting a pooled result?", "explanation": "The question, search, quality assessment, missing data and whether combining results is reasonable.", "pdf_page": 328, "card_id": "fc-021-4"}, {"id": "u-021-5", "level": "Deep Dive", "title": "What should a decision aid communicate besides options?", "explanation": "Relevant outcomes and probabilities, uncertainty, preference support, sources and possible conflicts of interest.", "pdf_page": 332, "card_id": "fc-021-5"}, {"id": "u-021-6", "level": "Deep Dive", "title": "Why appraise rather than merely name mechanistic evidence?", "explanation": "Its type, relevance and quality determine its contribution to the causal account.", "pdf_page": 333, "card_id": "fc-021-6"}], "outcomes": [{"id": "o-021-1", "text": "Select and justify the best response: An appraisal checklist records adequate randomisation, adequate follow-up and a valid outcome. The population differs substantially from the patients who would receive the intervention. Which conclusion should the checklist support?", "pdf_page": 325, "assessment_id": "q-021-1"}, {"id": "o-021-2", "text": "Select and justify the best response: A team uses a systematic-review checklist. The search is clear and the studies are eligible, but interventions and outcomes differ enough that a common summary may be misleading. Which checklist response is most appropriate?", "pdf_page": 328, "assessment_id": "q-021-2"}, {"id": "o-021-3", "text": "Select and justify the best response: A decision aid accurately states the favourable outcome probability but omits the comparison option, uncertainty and important burdens. Which revision most improves its ability to support choice?", "pdf_page": 332, "assessment_id": "q-021-3"}, {"id": "o-021-4", "text": "Select and justify the best response: Assertion (A): A trial can have good internal validity yet limited applicability to an excluded patient group.\n\nReason (R): A paired analysis recognises linkage between repeated observations from the same individual.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 325, "assessment_id": "q-021-4"}, {"id": "o-021-5", "text": "Select and justify the best response: A learner completes a checklist before deciding what the patient's priority problem is. Every methods box is marked satisfactory. Which missing action should take priority before applying the study?", "pdf_page": 323, "assessment_id": "q-021-5"}], "case_ids": ["q-021-1", "q-021-3"]}, {"num": 22, "hook": "Translate event rates into absolute and relative effects, with the event and follow-up period explicit.", "audience": "Healthcare students, practitioners and research learners. Beginners can start with units 1–5; experienced learners can select a relevant topic.", "prerequisites": "No advanced statistics assumed. Later units benefit from the question, design, bias and uncertainty foundations in units 1–5.", "minutes": 15, "units": [{"id": "u-022-1", "level": "Essentials", "title": "How is control event rate calculated?", "explanation": "Control participants with the event divided by all control participants: a/(a+b).", "pdf_page": 335, "card_id": "fc-022-1"}, {"id": "u-022-2", "level": "Essentials", "title": "How is experimental event rate calculated?", "explanation": "Experimental participants with the event divided by all experimental participants: c/(c+d).", "pdf_page": 335, "card_id": "fc-022-2"}, {"id": "u-022-3", "level": "Application", "title": "How is relative risk calculated?", "explanation": "Experimental event rate divided by control event rate, provided control event rate is nonzero.", "pdf_page": 335, "card_id": "fc-022-3"}, {"id": "u-022-4", "level": "Application", "title": "How is absolute risk reduction calculated for an undesirable event?", "explanation": "Control event rate minus experimental event rate; use proportions and preserve the outcome and time horizon.", "pdf_page": 335, "card_id": "fc-022-4"}, {"id": "u-022-5", "level": "Deep Dive", "title": "How is relative risk reduction calculated?", "explanation": "Derived from the relative-risk formula: RRR = 1 − RR = (CER − EER)/CER, when CER is nonzero. This is an authored algebraic explanation of the source formulas.", "pdf_page": 335, "card_id": "fc-022-5"}, {"id": "u-022-6", "level": "Deep Dive", "title": "How is NNT calculated for a positive absolute risk reduction?", "explanation": "The reciprocal of absolute risk reduction expressed as a proportion, for the specified outcome and follow-up period.", "pdf_page": 335, "card_id": "fc-022-6"}], "outcomes": [{"id": "o-022-1", "text": "Select and justify the best response: Over one year, 15 of 100 controls and 10 of 100 treated participants have an undesirable event. Which statement correctly compares absolute and relative effects?", "pdf_page": 335, "assessment_id": "q-022-1"}, {"id": "o-022-2", "text": "Select and justify the best response: A treatment has a one-year ARR of 0.025 for an undesirable event. A colleague calculates NNT as 1/2.5 = 0.4. What is the correct value for that endpoint and horizon?", "pdf_page": 335, "assessment_id": "q-022-2"}, {"id": "o-022-3", "text": "Select and justify the best response: A report compares recovery, a desirable outcome, in 60 of 100 treated people and 40 of 100 controls at three months. Which calculation gives the number needed to treat for one additional recovery over that period?", "pdf_page": 335, "assessment_id": "q-022-3"}, {"id": "o-022-4", "text": "Select and justify the best response: Assertion (A): Equal treated and control risks yield no finite NNT for benefit from their point estimates.\n\nReason (R): The relevant absolute risk reduction is zero, so its reciprocal is undefined.\n\nJudge the truth of each statement and whether R explains A.", "pdf_page": 335, "assessment_id": "q-022-4"}, {"id": "o-022-5", "text": "Select and justify the best response: Trial X has 20 events among 200 controls and 10 among 100 treated participants. Trial Y has 20 among 100 controls and 10 among 100 treated participants. Follow-up and endpoints match. Which comparison of ARR is correct?", "pdf_page": 335, "assessment_id": "q-022-5"}], "case_ids": ["q-022-1", "q-022-3"]}];